package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"time"
)

const (
	// MaxHopsLimit is the highest TTL a trace will probe.
	MaxHopsLimit = 30
	// DefaultProbeTimeout is how long one hop waits for an answer.
	DefaultProbeTimeout = 3 * time.Second
	// DeadlineLimit is the longest a whole trace may run.
	DeadlineLimit = 30 * time.Second
)

var (
	// ErrUnsupported is returned on platforms without a trace engine.
	ErrUnsupported = errors.New("path trace not supported on this platform")
	// ErrNotIPv4 is returned for a target that is not an IPv4 address.
	ErrNotIPv4 = errors.New("path trace supports IPv4 targets only")
	// ErrNotUnicast is returned for an unspecified, multicast or limited
	// broadcast target.
	ErrNotUnicast = errors.New("path trace needs a unicast target")
	// ErrNoRoute is returned when the system has no route to the target.
	ErrNoRoute = errors.New("no route to the target")
)

// Options tunes a trace. The zero value means "all defaults".
type Options struct {
	// MaxHops is the highest TTL probed, 1 to MaxHopsLimit.
	MaxHops int
	// ProbeTimeout is the wait for one hop's answer.
	ProbeTimeout time.Duration
	// Deadline bounds the whole trace.
	Deadline time.Duration
}

// Normalized returns the options with every out-of-range or unset value
// replaced by its default, and ProbeTimeout capped at Deadline.
func (o Options) Normalized() Options {
	if o.MaxHops <= 0 || o.MaxHops > MaxHopsLimit {
		o.MaxHops = MaxHopsLimit
	}
	if o.Deadline <= 0 || o.Deadline > DeadlineLimit {
		o.Deadline = DeadlineLimit
	}
	if o.ProbeTimeout <= 0 {
		o.ProbeTimeout = DefaultProbeTimeout
	}
	if o.ProbeTimeout > o.Deadline {
		o.ProbeTimeout = o.Deadline
	}
	return o
}

// HopKind says what a hop's probe got back.
type HopKind int

// The kinds of hop.
const (
	// HopSilent: no answer before the probe timeout.
	HopSilent HopKind = iota
	// HopRouter: an intermediate router answered (time exceeded).
	HopRouter
	// HopTarget: the target itself answered.
	HopTarget
	// HopUnreachable: a router reported the target as unreachable.
	HopUnreachable
	// HopUnresolved: an answer arrived but its sender could not be read.
	HopUnresolved
	// HopError: the probe could not be sent, or the answer was unexpected
	// (an error from the local stack, or a reply that is not ICMP).
	HopError
)

// String returns the kind's name.
func (k HopKind) String() string {
	switch k {
	case HopSilent:
		return "silent"
	case HopRouter:
		return "router"
	case HopTarget:
		return "target"
	case HopUnreachable:
		return "unreachable"
	case HopUnresolved:
		return "unresolved"
	case HopError:
		return "error"
	}
	return "unknown"
}

// Hop is the result of probing one TTL.
type Hop struct {
	TTL      int
	Kind     HopKind
	Addr     netip.Addr
	RTT      time.Duration
	ICMPType uint8
	ICMPCode uint8
	Err      error
}

// Outcome says why a trace ended.
type Outcome int

// The ways a trace ends. The zero value is OutcomeReached, so read an Outcome
// only when Trace returned no error.
const (
	// OutcomeReached: the target answered.
	OutcomeReached Outcome = iota
	// OutcomeMaxHops: MaxHops was exhausted without reaching the target.
	OutcomeMaxHops
	// OutcomeDeadline: the overall deadline expired.
	OutcomeDeadline
	// OutcomeCancelled: the caller's context was canceled.
	OutcomeCancelled
	// OutcomeUnreachable: a router reported the target as unreachable.
	OutcomeUnreachable
)

// String returns the outcome in US English.
func (o Outcome) String() string {
	switch o {
	case OutcomeReached:
		return "reached"
	case OutcomeMaxHops:
		return "max hops"
	case OutcomeDeadline:
		return "deadline"
	case OutcomeCancelled:
		return "canceled"
	case OutcomeUnreachable:
		return "unreachable"
	}
	return "unknown"
}

// Result is a finished trace.
//
// Hops is cut at the terminal hop (target reached or refused) or, when the
// trace ends at MaxHops, holds one hop per TTL. When a cancellation or the
// deadline ends it first, Hops holds exactly MaxHops entries, Hops[i].TTL ==
// i+1, and every probe that did not resolve is a HopUnresolved; so even with a
// terminal hop already known, the TTLs above it can show up as HopUnresolved.
// The probes above the target are all sent: only their wait is cut short.
//
// Always check the error Trace returned before
// reading it: the zero Result (and so the zero Outcome, OutcomeReached) means
// "no trace", never "reached".
type Result struct {
	Target   netip.Addr
	Outcome  Outcome
	Hops     []Hop
	Duration time.Duration
}

// Supported reports whether this platform can trace: nil, or ErrUnsupported.
func Supported() error {
	return supported()
}

// Trace probes the path to target. An IPv4-mapped IPv6 target is converted to
// IPv4; any other non-IPv4 target gets ErrNotIPv4 and nothing is sent. An
// unspecified (0.0.0.0), multicast or limited broadcast (255.255.255.255)
// target gets ErrNotUnicast. Subnet broadcasts cannot be told apart and are not
// checked. Loopback and private addresses are allowed: whether tracing them is
// acceptable is the caller's decision, at its own boundary.
//
// The errors Trace returns and Hop.Err carry raw platform text (errno
// messages): match the sentinels with errors.Is and show fixed labels, never
// that text in a summary.
func Trace(ctx context.Context, target netip.Addr, opts Options) (Result, error) {
	return TraceEach(ctx, target, opts, nil)
}

// TraceEach is Trace that also streams each hop as it resolves. onHop may be
// nil. It is called once per resolved hop (never for an unresolved one), one
// call at a time, from the goroutine that called TraceEach, and never after
// TraceEach has returned or for a target refused before any probe. Hops
// arrive in answer order, not TTL order. A hop above the terminal TTL may be
// reported while the terminal is still unknown; the Result is cut at the
// terminal hop, so the caller reconciles with it. The Result is the same as
// Trace's.
func TraceEach(ctx context.Context, target netip.Addr, opts Options, onHop func(Hop)) (Result, error) {
	if err := supported(); err != nil {
		return Result{}, err
	}
	target = target.Unmap()
	if !target.Is4() {
		return Result{}, ErrNotIPv4
	}
	if target.IsUnspecified() || target.IsMulticast() || target == netip.AddrFrom4([4]byte{255, 255, 255, 255}) {
		return Result{}, ErrNotUnicast
	}
	return run(ctx, target, opts, systemProber(), onHop)
}
//go:build !linux

package nettrace

import (
	"context"
	"net/netip"
)

func supported() error { return ErrUnsupported }

// unsupportedProber opens nothing: Trace stops at supported() first.
type unsupportedProber struct{}

func (unsupportedProber) open(context.Context, netip.Addr, int) (probeConn, error) {
	return nil, ErrUnsupported
}

// systemProber returns a prober that never opens a connection.
func systemProber() prober { return unsupportedProber{} }
//go:build !linux

package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"reflect"
	"testing"
)

func TestSupportedOffLinux(t *testing.T) {
	if err := Supported(); !errors.Is(err, ErrUnsupported) {
		t.Errorf("Supported() = %v, want ErrUnsupported", err)
	}
}

func TestTraceUnsupportedOffLinux(t *testing.T) {
	res, err := Trace(context.Background(), netip.MustParseAddr("192.0.2.1"), Options{})
	if !errors.Is(err, ErrUnsupported) {
		t.Fatalf("err = %v, want ErrUnsupported", err)
	}
	if !reflect.DeepEqual(res, Result{}) {
		t.Errorf("result = %+v, want the empty Result", res)
	}
}
package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"sync"
	"time"
)

// minEchoTimeout is the smallest timeout handed to an echo call: a zero or
// negative timeout is not a valid IcmpSendEcho argument.
const minEchoTimeout = time.Millisecond

// echoAPI is the ICMP echo service behind echoProber (Windows IcmpSendEcho).
// It is an interface so the engine's contract is tested on every platform.
type echoAPI interface {
	// create returns a new echo handle.
	create() (uintptr, error)
	// echo sends one echo request with the given TTL and blocks until it is
	// answered or timeout passes (errSilent). It cannot be interrupted.
	echo(h uintptr, dst netip.Addr, ttl int, timeout time.Duration) (reply, error)
	closeHandle(h uintptr) error
}

// echoProber probes with one echo handle per TTL.
type echoProber struct {
	api echoAPI
	// preflight runs before any handle is created: it tells a missing route
	// apart from a silent path. A no-route error becomes ErrNoRoute.
	preflight func(ctx context.Context, dst netip.Addr) error
}

func (p *echoProber) open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error) {
	if err := p.preflight(ctx, dst); err != nil {
		return nil, connectError(err)
	}
	h, err := p.api.create()
	if err != nil {
		return nil, err
	}
	return &echoConn{api: p.api, handle: h, dst: dst, ttl: ttl}, nil
}

// echoConn is single-use: one send, then one await. The echo call cannot be
// interrupted, so await runs it in a goroutine and abandons it on
// cancellation; the handle is then closed by that goroutine, never under it.
type echoConn struct {
	api    echoAPI
	handle uintptr
	dst    netip.Addr
	ttl    int

	mu       sync.Mutex
	inflight bool // an echo call is running on handle
	closed   bool // close was called
}

type echoResult struct {
	rep reply
	err error
}

func (c *echoConn) send() (time.Time, error) { return time.Now(), nil }

// await waits for the echo until the given time. It returns errSilent on
// timeout and ctx.Err() when ctx ended first.
func (c *echoConn) await(ctx context.Context, until time.Time) (reply, error) {
	if err := ctx.Err(); err != nil {
		return reply{}, err
	}
	timeout := max(time.Until(until), minEchoTimeout)

	c.mu.Lock()
	c.inflight = true
	c.mu.Unlock()
	done := make(chan echoResult, 1)
	go func() {
		rep, err := c.api.echo(c.handle, c.dst, c.ttl, timeout)
		c.echoReturned()
		done <- echoResult{rep, err}
	}()

	select {
	case <-ctx.Done():
		return reply{}, ctx.Err()
	case r := <-done:
		return c.settle(ctx, until, r)
	}
}

// settle turns an echo outcome into await's answer. When ctx's own deadline is
// not after until, the trace's deadline (not the probe timeout) is what ran
// out: let ctx report it, as the Linux connection does.
func (c *echoConn) settle(ctx context.Context, until time.Time, r echoResult) (reply, error) {
	if !errors.Is(r.err, errSilent) {
		return r.rep, r.err
	}
	if dl, ok := ctx.Deadline(); ok && !dl.After(until) {
		<-ctx.Done()
		return reply{}, ctx.Err()
	}
	return reply{}, errSilent
}

// echoReturned records that the echo call is over and closes the handle when
// close was asked for meanwhile.
func (c *echoConn) echoReturned() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.inflight = false
	if c.closed {
		_ = c.api.closeHandle(c.handle)
	}
}

// close releases the handle, once. While an echo is running the goroutine
// running it does so when it returns.
func (c *echoConn) close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed {
		return nil
	}
	c.closed = true
	if c.inflight {
		return nil
	}
	return c.api.closeHandle(c.handle)
}
package nettrace

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
)

// IP_STATUS values from ipexport.h (Windows SDK), spelled out so the mapping
// builds and is tested on every platform.
const (
	ipSuccess             = 0     // IP_SUCCESS
	ipDestNetUnreachable  = 11002 // IP_DEST_NET_UNREACHABLE
	ipDestHostUnreachable = 11003 // IP_DEST_HOST_UNREACHABLE
	ipDestProtUnreachable = 11004 // IP_DEST_PROT_UNREACHABLE
	ipDestPortUnreachable = 11005 // IP_DEST_PORT_UNREACHABLE
	ipReqTimedOut         = 11010 // IP_REQ_TIMED_OUT
	ipTTLExpiredTransit   = 11013 // IP_TTL_EXPIRED_TRANSIT
	ipTTLExpiredReassem   = 11014 // IP_TTL_EXPIRED_REASSEM
	ipDestUnreachable     = 11040 // IP_DEST_UNREACHABLE
	ipTimeExceeded        = 11041 // IP_TIME_EXCEEDED
	ipDestScopeMismatch   = 11045 // IP_DEST_SCOPE_MISMATCH
	ipGeneralFailure      = 11050 // IP_GENERAL_FAILURE
)

// originEcho marks a reply built from an ICMP echo status (Windows
// IcmpSendEcho). It is a DevDesk value outside the kernel's
// SO_EE_ORIGIN_* range, so it never collides with originLocal or originICMP.
const originEcho = 0xF0

// echoReplyMinLen is the part of ICMP_ECHO_REPLY this package reads: Address
// (4 bytes, network order) and Status (4 bytes, little-endian).
const echoReplyMinLen = 8

// EchoStatusError reports an ICMP echo status that carries no usable hop.
// Its text is ASCII only, never a localized system message.
type EchoStatusError struct {
	Status uint32
}

func (e *EchoStatusError) Error() string {
	return fmt.Sprintf("ICMP status %d", e.Status)
}

// echoReply builds the reply for an echo status and the address that
// answered (which may be the zero address). A timeout is errSilent; a general
// failure or an unknown status is an *EchoStatusError.
func echoReply(status uint32, from netip.Addr) (reply, error) {
	var icmpType uint8
	switch status {
	case ipSuccess:
		icmpType = 0
	case ipTTLExpiredTransit:
		icmpType = icmpTimeExceeded
	case ipReqTimedOut:
		return reply{}, errSilent
	case ipDestNetUnreachable, ipDestHostUnreachable, ipDestProtUnreachable,
		ipDestPortUnreachable, ipTTLExpiredReassem, ipDestUnreachable,
		ipTimeExceeded, ipDestScopeMismatch:
		// Kept as is: classifyEcho decides what they mean.
	default: // ipGeneralFailure and anything unknown
		return reply{}, &EchoStatusError{Status: status}
	}
	return reply{Addr: from, ICMPType: icmpType, Origin: originEcho, Status: status}, nil
}

// classifyEcho maps an echo-status reply to the kind of hop it reveals.
func classifyEcho(r reply, _ netip.Addr) HopKind {
	switch r.Status {
	case ipSuccess:
		return HopTarget
	case ipTTLExpiredTransit:
		return HopRouter
	case ipDestNetUnreachable, ipDestHostUnreachable,
		ipDestProtUnreachable, ipDestPortUnreachable:
		return HopUnreachable
	}
	return HopError
}

// decodeEchoReply4 reads the address and status from an ICMP_ECHO_REPLY.
func decodeEchoReply4(buf []byte) (netip.Addr, uint32, error) {
	if len(buf) < echoReplyMinLen {
		return netip.Addr{}, 0, errors.New("echo reply too short")
	}
	return netip.AddrFrom4([4]byte(buf[0:4])), binary.LittleEndian.Uint32(buf[4:8]), nil
}

