package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"sync"
	"time"
)

// minEchoTimeout is the smallest timeout handed to an echo call: a zero or
// negative timeout is not a valid IcmpSendEcho argument.
const minEchoTimeout = time.Millisecond

// echoAPI is the ICMP echo service behind echoProber (Windows IcmpSendEcho).
// It is an interface so the engine's contract is tested on every platform.
type echoAPI interface {
	// create returns a new echo handle.
	create() (uintptr, error)
	// echo sends one echo request with the given TTL and blocks until it is
	// answered or timeout passes (errSilent). It cannot be interrupted.
	echo(h uintptr, dst netip.Addr, ttl int, timeout time.Duration) (reply, error)
	closeHandle(h uintptr) error
}

// echoProber probes with one echo handle per TTL.
type echoProber struct {
	api echoAPI
	// preflight runs before any handle is created: it tells a missing route
	// apart from a silent path. A no-route error becomes ErrNoRoute.
	preflight func(ctx context.Context, dst netip.Addr) error
}

func (p *echoProber) open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error) {
	if err := p.preflight(ctx, dst); err != nil {
		return nil, connectError(err)
	}
	h, err := p.api.create()
	if err != nil {
		return nil, err
	}
	return &echoConn{api: p.api, handle: h, dst: dst, ttl: ttl}, nil
}

// echoConn is single-use: one send, then one await. The echo call cannot be
// interrupted, so await runs it in a goroutine and abandons it on
// cancellation; the handle is then closed by that goroutine, never under it.
type echoConn struct {
	api    echoAPI
	handle uintptr
	dst    netip.Addr
	ttl    int

	mu       sync.Mutex
	inflight bool // an echo call is running on handle
	closed   bool // close was called
}

type echoResult struct {
	rep reply
	err error
}

func (c *echoConn) send() (time.Time, error) { return time.Now(), nil }

// await waits for the echo until the given time. It returns errSilent on
// timeout and ctx.Err() when ctx ended first.
func (c *echoConn) await(ctx context.Context, until time.Time) (reply, error) {
	if err := ctx.Err(); err != nil {
		return reply{}, err
	}
	timeout := max(time.Until(until), minEchoTimeout)

	c.mu.Lock()
	c.inflight = true
	c.mu.Unlock()
	done := make(chan echoResult, 1)
	go func() {
		rep, err := c.api.echo(c.handle, c.dst, c.ttl, timeout)
		c.echoReturned()
		done <- echoResult{rep, err}
	}()

	select {
	case <-ctx.Done():
		return reply{}, ctx.Err()
	case r := <-done:
		return c.settle(ctx, until, r)
	}
}

// settle turns an echo outcome into await's answer. When ctx's own deadline is
// not after until, the trace's deadline (not the probe timeout) is what ran
// out: let ctx report it, as the Linux connection does.
func (c *echoConn) settle(ctx context.Context, until time.Time, r echoResult) (reply, error) {
	if !errors.Is(r.err, errSilent) {
		return r.rep, r.err
	}
	if dl, ok := ctx.Deadline(); ok && !dl.After(until) {
		<-ctx.Done()
		return reply{}, ctx.Err()
	}
	return reply{}, errSilent
}

// echoReturned records that the echo call is over and closes the handle when
// close was asked for meanwhile.
func (c *echoConn) echoReturned() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.inflight = false
	if c.closed {
		_ = c.api.closeHandle(c.handle)
	}
}

// close releases the handle, once. While an echo is running the goroutine
// running it does so when it returns.
func (c *echoConn) close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed {
		return nil
	}
	c.closed = true
	if c.inflight {
		return nil
	}
	return c.api.closeHandle(c.handle)
}
package nettrace

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
)

// IP_STATUS values from ipexport.h (Windows SDK), spelled out so the mapping
// builds and is tested on every platform.
const (
	ipSuccess             = 0     // IP_SUCCESS
	ipDestNetUnreachable  = 11002 // IP_DEST_NET_UNREACHABLE
	ipDestHostUnreachable = 11003 // IP_DEST_HOST_UNREACHABLE
	ipDestProtUnreachable = 11004 // IP_DEST_PROT_UNREACHABLE
	ipDestPortUnreachable = 11005 // IP_DEST_PORT_UNREACHABLE
	ipReqTimedOut         = 11010 // IP_REQ_TIMED_OUT
	ipTTLExpiredTransit   = 11013 // IP_TTL_EXPIRED_TRANSIT
	ipTTLExpiredReassem   = 11014 // IP_TTL_EXPIRED_REASSEM
	ipDestUnreachable     = 11040 // IP_DEST_UNREACHABLE
	ipTimeExceeded        = 11041 // IP_TIME_EXCEEDED
	ipDestScopeMismatch   = 11045 // IP_DEST_SCOPE_MISMATCH
	ipGeneralFailure      = 11050 // IP_GENERAL_FAILURE
)

// originEcho marks a reply built from an ICMP echo status (Windows
// IcmpSendEcho). It is a DevDesk value outside the kernel's
// SO_EE_ORIGIN_* range, so it never collides with originLocal or originICMP.
const originEcho = 0xF0

// echoReplyMinLen is the part of ICMP_ECHO_REPLY this package reads: Address
// (4 bytes, network order) and Status (4 bytes, little-endian).
const echoReplyMinLen = 8

// EchoStatusError reports an ICMP echo status that carries no usable hop.
// Its text is ASCII only, never a localized system message.
type EchoStatusError struct {
	Status uint32
}

func (e *EchoStatusError) Error() string {
	return fmt.Sprintf("ICMP status %d", e.Status)
}

// echoReply builds the reply for an echo status and the address that
// answered (which may be the zero address). A timeout is errSilent; a general
// failure or an unknown status is an *EchoStatusError.
func echoReply(status uint32, from netip.Addr) (reply, error) {
	var icmpType uint8
	switch status {
	case ipSuccess:
		icmpType = 0
	case ipTTLExpiredTransit:
		icmpType = icmpTimeExceeded
	case ipReqTimedOut:
		return reply{}, errSilent
	case ipDestNetUnreachable, ipDestHostUnreachable, ipDestProtUnreachable,
		ipDestPortUnreachable, ipTTLExpiredReassem, ipDestUnreachable,
		ipTimeExceeded, ipDestScopeMismatch:
		// Kept as is: classifyEcho decides what they mean.
	default: // ipGeneralFailure and anything unknown
		return reply{}, &EchoStatusError{Status: status}
	}
	return reply{Addr: from, ICMPType: icmpType, Origin: originEcho, Status: status}, nil
}

// classifyEcho maps an echo-status reply to the kind of hop it reveals.
func classifyEcho(r reply, _ netip.Addr) HopKind {
	switch r.Status {
	case ipSuccess:
		return HopTarget
	case ipTTLExpiredTransit:
		return HopRouter
	case ipDestNetUnreachable, ipDestHostUnreachable,
		ipDestProtUnreachable, ipDestPortUnreachable:
		return HopUnreachable
	}
	return HopError
}

// decodeEchoReply4 reads the address and status from an ICMP_ECHO_REPLY.
func decodeEchoReply4(buf []byte) (netip.Addr, uint32, error) {
	if len(buf) < echoReplyMinLen {
		return netip.Addr{}, 0, errors.New("echo reply too short")
	}
	return netip.AddrFrom4([4]byte(buf[0:4])), binary.LittleEndian.Uint32(buf[4:8]), nil
}

